mapper.update:
update shopping_cart
set number = #{number},
    amount = #{amount}
where id=#{id};

mapper.select:
SELECT sc.id, sc.table_id, sc.dish_id, sc.name, sc.image, sc.number, (d.price * sc.number) AS amount FROM shopping_cart sc LEFT JOIN dish d ON sc.dish_id = d.id
AND sc.table_id = #{tableId}
AND sc.dish_id = #{dishId}
ORDER BY sc.create_time DESC
